[hidden] { display: none !important; }
:root {
  color-scheme: light;
  --ink: #26352d;
  --cream: #fff9e9;
  --green: #315e4b;
  --mint: #d7ead7;
  --coral: #e88768;
}
* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 24px;
  display: grid;
  place-items: center;
  background-color: var(--green);
  background-image: radial-gradient(#ffffff18 1px, transparent 1px);
  background-size: 18px 18px;
  color: var(--ink);
  font: 16px/1.5 system-ui, sans-serif;
}
.board {
  width: min(100%, 620px);
  padding: clamp(24px, 6vw, 48px);
  border: 4px solid var(--ink);
  border-radius: 12px;
  background: var(--cream);
  box-shadow: 8px 8px 0 #1e3d30;
  text-align: center;
}
.eyebrow { margin: 0 0 8px; color: var(--green); font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(2rem, 8vw, 3rem); line-height: 1.1; }
.intro { margin: 14px auto 30px; max-width: 38ch; }
.game { padding: 22px; border: 2px dashed #9bb89d; border-radius: 8px; background: var(--mint); }
.status-row { display: flex; justify-content: space-between; gap: 12px; font-weight: 700; }
.status-row p { margin: 0 0 18px; }
.dice { display: flex; justify-content: center; flex-wrap: wrap; gap: 12px; }
.die {
  width: clamp(48px, 12vw, 64px);
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  border: 3px solid var(--ink);
  border-radius: 9px;
  background: var(--cream);
  color: var(--ink);
  font: 700 2rem/1 system-ui, sans-serif;
  box-shadow: 0 4px 0 #26352d33;
  cursor: pointer;
  transition: transform .12s, background .12s, box-shadow .12s;
}
.die:hover { transform: translateY(-3px); }
.die:active { transform: translateY(2px); box-shadow: none; }
.die[aria-pressed="true"] { background: var(--coral); transform: translateY(-4px); box-shadow: 0 6px 0 #26352d33; }
button:focus-visible, .die:focus-visible { outline: 4px solid var(--coral); outline-offset: 4px; }
.hint { margin: 18px 0; }
.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; }
button:not(.die) { min-height: 48px; padding: 10px 20px; border: 2px solid var(--ink); border-radius: 6px; background: var(--cream); color: var(--ink); font: inherit; font-weight: 700; cursor: pointer; transition: transform .12s, background .12s; }
button:not(.die):hover { transform: translateY(-2px); background: #fff; }
button:not(.die):active { transform: translateY(2px); }
button.primary { background: var(--green); color: var(--cream); }
button.primary:hover { background: #244a39; }
button:disabled { opacity: .55; cursor: not-allowed; transform: none; }
footer { margin-top: 24px; color: var(--green); font-weight: 600; }
@media (max-width: 420px) {
  body { padding: 14px; }
  .board { padding: 24px 16px; }
  .game { padding: 18px 12px; }
  .status-row { flex-direction: column; gap: 2px; }
  .status-row p { margin-bottom: 8px; }
}

const diceArea = document.querySelector('#dice');
const rollButton = document.querySelector('#roll-button');
const newButton = document.querySelector('#new-button');
const rollCount = document.querySelector('#roll-count');
const handName = document.querySelector('#hand-name');

let values = [];
let held = [];
let rollsLeft = 2;
let finished = false;

function rollDie() {
  return Math.floor(Math.random() * 6) + 1;
}

function handFor(dice) {
  const counts = Array(7).fill(0);
  dice.forEach(value => counts[value]++);
  const groups = counts.filter(count => count > 0).sort((a, b) => b - a);
  if (groups[0] === 5) return 'Five of a kind';
  if (groups[0] === 4) return 'Four of a kind';
  if (groups[0] === 3 && groups[1] === 2) return 'Full house';
  const unique = [...new Set(dice)].sort((a, b) => a - b).join('');
  if (unique === '12345' || unique === '23456') return 'Straight';
  if (groups[0] === 3) return 'Three of a kind';
  if (groups[0] === 2 && groups[1] === 2) return 'Two pair';
  if (groups[0] === 2) return 'Pair';
  return 'High die';
}

function render() {
  diceArea.replaceChildren();
  values.forEach((value, index) => {
    const die = document.createElement('button');
    die.type = 'button';
    die.className = 'die';
    die.textContent = String(value);
    die.setAttribute('aria-label', `Die ${index + 1}: ${value}${held[index] ? ', held' : ', not held'}`);
    die.setAttribute('aria-pressed', String(held[index]));
    die.addEventListener('click', () => {
      if (finished) return;
      held[index] = !held[index];
      render();
      diceArea.children[index].focus();
    });
    diceArea.append(die);
  });
  rollCount.textContent = `Rolls left: ${rollsLeft}`;
  rollButton.disabled = finished || rollsLeft === 0;
  handName.textContent = finished ? `Your hand: ${handFor(values)}` : 'Your hand: —';
}

function startRound() {
  values = Array.from({ length: 5 }, rollDie);
  held = Array(5).fill(false);
  rollsLeft = 2;
  finished = false;
  render();
}

rollButton.addEventListener('click', () => {
  if (finished || rollsLeft === 0) return;
  values = values.map((value, index) => held[index] ? value : rollDie());
  rollsLeft--;
  if (rollsLeft === 0) finished = true;
  render();
});
newButton.addEventListener('click', startRound);
startRound();
